/// <summary>
/// designed from AVA
/// </summary>
/// <returns>boolean</returns>
public boolean modified()
{
    boolean         retVal;
    HCMWorkerRecId  qValue;

    FormDataSource  locSalesTableDS;
    FormDataSource  locSalesLineDS;

    locSalesTableDS = element.SalesTable_DS;
    locSalesLineDS  = element.SalesLine_DS;

    retVal = next modified();

    qValue = element.GridFilterWorkerSalesTaker.value();

    if (qValue != 0)
    {
        SysQuery::findOrCreateRange(locSalesTableDS.queryBuildDataSource(), fieldNum(SalesTable, WorkerSalesTaker)).value(queryValue(qValue));
    }
    else
    {
        //SysQuery::findOrCreateRange(locSalesTableDS.queryBuildDataSource(), fieldNum(SalesTable, WorkerSalesTaker)).value(SysQueryRangeUtil::valueUnlimited());
        //SysQuery::findOrCreateRange(locSalesTableDS.queryBuildDataSource(), fieldNum(SalesTable, WorkerSalesTaker)).value(SysQuery::valueNot(0));
        locSalesTableDS.queryBuildDataSource().clearRange(fieldNum(SalesTable, WorkerSalesTaker));
    }

    locSalesLineDS.executeQuery();

    return retVal;
}

